    READ_IN_MUTABLE_PARAMS;
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseA(pNonce * 0xB3E402D08AF303D5ULL + 0x92856E8E0691A3F7ULL);
