            aOrbiterG = (aOrbiterG + aOrbiterC) + 0xEA70B2D0294A3C1BULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterG) ^ 0xEBC6BFB3E02AB898ULL) ^ aTwistOrbiterUpdateSaltE[((aIndex + 179U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x3F7BC8227D5272CFULL), 5U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterA) + 0x0567103737818ADFULL;
