            aOrbiterH = ((aWandererI + RotL64(aScatter, 47U)) + 0xC3405E5753B3BFBDULL) + aTwistOrbiterAssignSaltD[(((255U - aIndex) + 56U)) & S_SALT1];
            aOrbiterJ = (aWandererA + RotL64(aCross, 35U)) + 0x794B07E1D3A8672DULL;
