            //
            aOrbiterI = (aOrbiterI + aOrbiterH) + 0xB6CB9BAC32B12C88ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterI) ^ 0xF1102F2F97953330ULL) ^ aTwistOrbiterUpdateSaltF[(((255U - aIndex) + 187U)) & S_SALT1];
