            //
            aOrbiterJ = (aOrbiterJ + aOrbiterE) + 0x96ED8DB975C88942ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterJ) ^ 0xC4D84E4A24C5CE59ULL;
