            aCross = (RotL64(aWindLaneC[((S_BLOCK1 - aIndex + 8108U)) & S_BLOCK1], 6U) ^ RotL64(aWindLaneA[((S_BLOCK1 - aIndex + 3266U)) & S_BLOCK1], 51U));
