            aScatter = (RotL64(aCross, 41U) ^ RotL64(aPrevious, 29U)) ^ (RotL64(aIngress, 53U) + RotL64(aCarry, 10U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterB = ((aWandererK + RotL64(aCross, 47U)) + 0xE393A8B505BF2D0AULL) + aKeyRotateAOrbiterAssignSaltA[(((255U - aIndex) + 25U)) & S_SALT1];
            aOrbiterH = ((aWandererC + RotL64(aPrevious, 3U)) + 0xDDBE8F013472975DULL) + aKeyRotateAOrbiterAssignSaltF[(((255U - aIndex) + 125U)) & S_SALT1];
            aOrbiterD = ((aWandererI + RotL64(aIngress, 56U)) + RotL64(aCarry, 43U)) + 0x5CAE43B773E49D6CULL;
            aOrbiterI = ((aWandererB + RotL64(aScatter, 35U)) + RotL64(aCarry, 29U)) + 0x9674139AA42E503CULL;
            aOrbiterF = ((aWandererD + RotL64(aPrevious, 41U)) + RotL64(aCarry, 3U)) + 0xFA3CFAA412CA166CULL;
            aOrbiterJ = (aWandererH + RotL64(aScatter, 27U)) + 0x9D84E1EBA7B2888FULL;
            aOrbiterG = (aWandererG + RotL64(aCross, 21U)) + 0x9B7CF645BEF25945ULL;
            //
            aOrbiterB = (aOrbiterB + aOrbiterH) + 0xA9C5FCB24A1C4A13ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterB) ^ 0xCA9B266B0179AE6AULL;
            aOrbiterD = RotL64((aOrbiterD * 0xD4729B2656A6A821ULL), 35U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterB) + 0x2FC318322904E76CULL) + aKeyRotateAOrbiterUpdateSaltC[(((255U - aIndex) + 109U)) & S_SALT1];
            aOrbiterF = ((aOrbiterF ^ aOrbiterI) ^ 0xCBEBD23A10C546D8ULL) ^ aKeyRotateAOrbiterUpdateSaltE[((aIndex + 143U)) & S_SALT1];
