            aOrbiterB = RotL64((aOrbiterB * 0xAA56504664ADFBF5ULL), 27U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterF) + 0x4E86AF59989B24F9ULL) + aKeyRotateAOrbiterUpdateSaltF[((aIndex + 252U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterG) ^ 0xE28AF73F2B5F49CAULL;
