            //
            aOrbiterD = (aOrbiterD + aOrbiterI) + 0x810B0426502485ACULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterD) ^ 0x884078D963D60262ULL) ^ aKeyRotateAOrbiterUpdateSaltA[(((255U - aIndex) + 183U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x9B0F54CD51AD8C07ULL), 3U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterJ) + 0x27DA916219B0ADC7ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterH) ^ 0x3C9F590F8A0C1DB7ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x47D20C7ACC2F8C5DULL), 53U);
            //
            aIngress = RotL64(aOrbiterG, 34U) ^ aOrbiterB;
            aIngress = aIngress + (aOrbiterI ^ RotL64(aOrbiterJ, 43U));
            aIngress = aIngress + (RotL64(aOrbiterF, 5U) ^ aOrbiterH);
            aIngress = aIngress + RotL64(aOrbiterD, 11U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererG = aWandererG ^ (((RotL64(aIngress, 5U) + aOrbiterI) + RotL64(aOrbiterD, 27U)) + aKeyRotateAWandererUpdateSaltB[((aIndex + 66U)) & S_SALT1]);
            aWandererK = aWandererK + (((RotL64(aPrevious, 53U) + RotL64(aOrbiterF, 4U)) + aOrbiterG) + RotL64(aCarry, 11U));
