            aCross = (RotL64(aWindLaneD[((S_BLOCK1 - aIndex + 13529U)) & S_BLOCK1], 3U) ^ RotL64(aWindLaneB[((S_BLOCK1 - aIndex + 16312U)) & S_BLOCK1], 13U));
            aCross ^= (RotL64(aPoisonLaneD[((S_BLOCK1 - aIndex + 15500U)) & S_BLOCK1], 42U) ^ RotL64(aSoilLaneC[((aIndex + 12038U)) & S_BLOCK1], 27U));
            aCross = TwistMix64::DiffuseB((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aIngress, 41U) ^ RotL64(aCross, 21U)) + (RotL64(aCarry, 5U) + RotL64(aPrevious, 56U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterE = (aWandererI + RotL64(aIngress, 13U)) + 0x413E3E41A48B46CAULL;
            aOrbiterD = (aWandererF + RotL64(aCross, 37U)) + 0x3C1FDE7D9080F985ULL;
            aOrbiterF = (((aWandererK + RotL64(aScatter, 27U)) + RotL64(aCarry, 27U)) + 0x99BCB9D96E9E6182ULL) + aKeyRotateAOrbiterAssignSaltE[(((255U - aIndex) + 49U)) & S_SALT1];
            aOrbiterH = ((aWandererJ + RotL64(aPrevious, 57U)) + RotL64(aCarry, 11U)) + 0x65EB6E53D2CAD642ULL;
            aOrbiterK = ((aWandererH + RotL64(aIngress, 19U)) + RotL64(aCarry, 53U)) + 0x93828B926E83CD44ULL;
            aOrbiterG = ((aWandererG + RotL64(aCross, 44U)) + 0x66761B33D748C4E8ULL) + aKeyRotateAOrbiterAssignSaltC[((aIndex + 213U)) & S_SALT1];
            aOrbiterB = (aWandererC + RotL64(aScatter, 3U)) + 0x0A664B50D444D122ULL;
            //
            aOrbiterE = (aOrbiterE + aOrbiterD) + 0xD457889C0AF761A3ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterE) ^ 0x121A8A1AA9BA6F30ULL) ^ aKeyRotateAOrbiterUpdateSaltF[((aIndex + 43U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x06465C1AFC1C6A5BULL), 53U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterH) + 0x509DE62C8270F0F5ULL) + aKeyRotateAOrbiterUpdateSaltC[((aIndex + 47U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterD) ^ 0x6CBF7E4DBAC3D37AULL;
            aOrbiterK = RotL64((aOrbiterK * 0x4974CC49040C5861ULL), 11U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterG) + 0x8927D405D6D5D61EULL) + aKeyRotateAOrbiterUpdateSaltB[(((255U - aIndex) + 116U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterK) ^ 0x3D4AC1967D37152EULL;
            aOrbiterE = RotL64((aOrbiterE * 0x5BE5E10DE060E737ULL), 27U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterK) + 0xBA5DD531E323CCFDULL) + aKeyRotateAOrbiterUpdateSaltD[(((255U - aIndex) + 2U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterF) ^ 0x92AB4521EB6BF95BULL;
            aOrbiterB = RotL64((aOrbiterB * 0x8B8E7965095A252DULL), 3U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterF) + 0x084C944E10ED4056ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterH) ^ 0x0E9C0BD9C721CC4FULL;
            aOrbiterG = RotL64((aOrbiterG * 0x7DA4E4F1EBE5D021ULL), 35U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterB) + 0x34ABF410B3D2B63CULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterG) ^ 0x256F18E68A452210ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xAEF212EAB91DEBABULL), 41U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterE) + 0x12D6ED69C38BD7C1ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0xB9EBFAC8A61C0A5CULL;
            aOrbiterH = RotL64((aOrbiterH * 0x4E39E0605593158FULL), 47U);
            //
            aIngress = aOrbiterE ^ RotL64(aOrbiterB, 57U);
            aIngress = aIngress + (aOrbiterF ^ RotL64(aOrbiterG, 27U));
            aIngress = aIngress + (aOrbiterH ^ RotL64(aOrbiterK, 42U));
            aIngress = aIngress + RotL64(aOrbiterD, 13U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererF = aWandererF + ((RotL64(aIngress, 60U) + aOrbiterK) + RotL64(aOrbiterE, 3U));
            aWandererC = aWandererC ^ ((RotL64(aScatter, 37U) + RotL64(aOrbiterG, 47U)) + aOrbiterH);
            aWandererJ = aWandererJ + ((((RotL64(aCross, 21U) + RotL64(aOrbiterB, 22U)) + aOrbiterE) + RotL64(aCarry, 27U)) + aKeyRotateAWandererUpdateSaltC[((aIndex + 19U)) & S_SALT1]);
            aWandererG = aWandererG ^ ((RotL64(aPrevious, 5U) + aOrbiterK) + RotL64(aOrbiterF, 39U));
            aWandererK = aWandererK + (((RotL64(aScatter, 11U) + RotL64(aOrbiterD, 13U)) + aOrbiterK) + aKeyRotateAWandererUpdateSaltF[((aIndex + 37U)) & S_SALT1]);
            aWandererI = aWandererI ^ ((RotL64(aPrevious, 43U) + RotL64(aOrbiterG, 53U)) + aOrbiterK);
            aWandererH = aWandererH + (((RotL64(aIngress, 27U) + RotL64(aOrbiterH, 29U)) + aOrbiterK) + RotL64(aCarry, 53U));
