            aCross = (RotL64(aFuseLaneA[((S_BLOCK1 - aIndex + 18909U)) & S_BLOCK1], 24U) ^ RotL64(aWindLaneC[((S_BLOCK1 - aIndex + 19561U)) & S_BLOCK1], 57U));
            aCross ^= (RotL64(aShadowLaneD[((S_BLOCK1 - aIndex + 22878U)) & S_BLOCK1], 43U) ^ RotL64(aPoisonLaneA[((S_BLOCK1 - aIndex + 23098U)) & S_BLOCK1], 35U));
            aCross = TwistMix64::DiffuseC((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aCross, 37U) ^ RotL64(aPrevious, 21U)) + (RotL64(aCarry, 56U) ^ RotL64(aIngress, 5U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterD = (aWandererJ + RotL64(aPrevious, 27U)) + 0x085BA196CF4350A6ULL;
            aOrbiterG = ((aWandererC + RotL64(aCross, 41U)) + 0x876DB7BD195A70E1ULL) + aKeyRotateAOrbiterAssignSaltD[((aIndex + 135U)) & S_SALT1];
