            aOrbiterD = (((aWandererE + RotL64(aCross, 27U)) + RotL64(aCarry, 43U)) + 0x716087467C092068ULL) + aKeyRotateBOrbiterAssignSaltB[((aIndex + 144U)) & S_SALT1];
